CR = r"Окружности $x^{2}+y^{2}=9$ и $x^{2}+y^{2}=16$ делят плоскость на три области. Где расположена точка $%s$?"
REG = [r"внутри малой окружности", r"в кольце между окружностями", r"вне большой окружности", r"на одной из окружностей"]
def reg(pt, s, k):
    w = {0: r"Ученик ошибся при сравнении: $x^{2}+y^{2}=%s$; точка внутри малой окружности, если это меньше $9$." % s,
         1: r"Ученик ошибся при сравнении: $x^{2}+y^{2}=%s$; точка в кольце, если $9<x^{2}+y^{2}<16$." % s,
         2: r"Ученик ошибся при сравнении: $x^{2}+y^{2}=%s$; точка вне большой окружности, если это больше $16$." % s,
         3: r"Ученик решил, что точка лежит на окружности; $x^{2}+y^{2}=%s$ не равно ни $9$, ни $16$." % s}
    return Q(CR % pt, REG[k], [(REG[i], w[i]) for i in range(4) if i != k])
T("G9_TB_20_380", "несколько точек в одной задаче; каждая точка — отдельная задача", [
 reg(r"N(1;\,-2)", "5", 0), reg(r"P(3{,}6;\,0)", r"12{,}96", 1), reg(r"Q(4{,}001;\,-0{,}5)", r"16{,}258001", 2),
])
TS = r"Верно ли утверждение $%s$?"
T("G9_TB_2_17", "список из двенадцати утверждений в одной задаче; выделены отдельные вопросы «да/нет»", [
 YN(TS % r"3{,}38\notin\mathbb{Q}", "нет", r"Ученик не узнал рациональное число: $3{,}38=\dfrac{338}{100}\in\mathbb{Q}$."),
 YN(TS % r"\sqrt{2}\in\mathbb{Q}", "нет", r"Ученик не знает, что $\sqrt{2}$ — иррациональное число."),
 YN(TS % r"4+\sqrt{4}\in\mathbb{Z}", "да", r"Ученик не вычислил: $4+\sqrt{4}=4+2=6\in\mathbb{Z}$."),
 YN(TS % r"\dfrac{12}{15}\in\mathbb{N}", "нет", r"Ученик не заметил, что $\dfrac{12}{15}=\dfrac{4}{5}$ — не натуральное число."),
])
